3044	 * Name: i2s_txchannels
3045	 *
3046	 * Description:
3047	 *   Set the I2S TX number of channels.
3048	 *
3049	 * Input Parameters:
3050	 *   dev  - Device-specific state data
3051	 *   channels - The I2S numbers of channels
3052	 *
3053	 * Returned Value:
3054	 *   OK on success; a negated errno value on failure.
3055	 *
3056	 ****************************************************************************/
3057	
3058	static int i2s_txchannels(struct i2s_dev_s *dev, uint8_t channels)
3059	{
3060	  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)dev;
3061	  uint32_t channels_mask;
3062	
3063	  if (priv->config->tx_en)
3064	    {
3065	      if (channels != 1 && channels != 2)
3066	        {
3067	          return -EINVAL;
3068	        }
3069	
3070	      i2s_tx_channel_stop(priv);
3071	
3072	      priv->channels = channels;
3073	
3074	      /* Always consider two channels. For mono (1-channel), we set the
3075	       * I2S_TX_TDM_CHAN1_EN to 0 and I2S_TX_CHAN_EQUAL to 1 to send out
3076	       * the data of the previous channel.
3077	       */
3078	
3079	      /* TOT_CHAN_NUM = total_slot - 1 (N+1 encoding)
3080	       * Channel mask = (1 << total_slot) - 1
3081	       */
3082	
3083	      modifyreg32(I2S_TX_TDM_CTRL_REG(priv->config->port),
3084	                  I2S_TX_TDM_TOT_CHAN_NUM_M,
3085	                  FIELD_TO_VALUE(I2S_TX_TDM_TOT_CHAN_NUM,
3086	                                 priv->config->total_slot - 1));
3087	
3088	      channels_mask = getreg32(I2S_TX_TDM_CTRL_REG(priv->config->port));
3089	      channels_mask &= 0xffff0000;
3090	
3091	      if (priv->channels == 1)
3092	        {
3093	          modifyreg32(I2S_TX_CONF_REG(priv->config->port),
3094	                      I2S_TX_MONO_M, I2S_TX_MONO);
3095	          modifyreg32(I2S_TX_CONF_REG(priv->config->port),
3096	                      I2S_TX_CHAN_EQUAL_M, I2S_TX_CHAN_EQUAL);
3097	          channels_mask |= I2S_TX_TDM_CHAN0_EN;
3098	        }
3099	      else
3100	        {
3101	          modifyreg32(I2S_TX_CONF_REG(priv->config->port),
3102	                      I2S_TX_MONO_M, 0);
3103	          modifyreg32(I2S_TX_CONF_REG(priv->config->port),
3104	                      I2S_TX_CHAN_EQUAL_M, 0);
3105	          channels_mask |= (uint32_t)((1u << priv->config->total_slot) - 1);
3106	        }
3107	
3108	      putreg32(channels_mask, I2S_TX_TDM_CTRL_REG(priv->config->port));
3109	
3110	      /* Set I2S_TX_UPDATE bit to update the configs.
3111	       * This bit is automatically cleared.
3112	       */
3113	
3114	      modifyreg32(I2S_TX_CONF_REG(priv->config->port),
3115	                  0, I2S_TX_UPDATE);
3116	
3117	      i2s_tx_channel_start(priv);
3118	
3119	      syslog(LOG_INFO,
3120	             "i2s_txchannels: ch=%u tx_conf=0x%08lx tx_tdm=0x%08lx\n",
3121	             priv->channels,
3122	             (unsigned long)getreg32(I2S_TX_CONF_REG(priv->config->port)),
3123	             (unsigned long)getreg32(
3124	               I2S_TX_TDM_CTRL_REG(priv->config->port)));
3125	
3126	      return OK;
3127	    }
3128	
3129	  return -ENOTTY;
3130	}
