3369	/****************************************************************************
3370	 * Name: i2s_rxdatawidth
3371	 *
3372	 * Description:
3373	 *   Set the I2S RX data width.  The RX bitrate is determined by
3374	 *   sample_rate * data_width.
3375	 *
3376	 * Input Parameters:
3377	 *   dev   - Device-specific state data
3378	 *   width - The I2S data with in bits.
3379	 *
3380	 * Returned Value:
3381	 *   Returns the resulting data width
3382	 *
3383	 ****************************************************************************/

2163	 * Name: i2s_set_clock
2164	 *
2165	 * Description:
2166	 *   Set the I2S TX sample rate by adjusting I2S clock.
2167	 *
2168	 * Input Parameters:
2169	 *   priv - Initialized I2S device structure.
2170	 *
2171	 * Returned Value:
2172	 *   Returns the resulting bitrate
2173	 *
2174	 ****************************************************************************/
2175	
2176	static uint32_t i2s_set_clock(struct esp32s3_i2s_s *priv)
2177	{
2178	  uint32_t rate;
2179	  uint32_t bclk;
2180	  uint32_t mclk;
2181	  uint32_t sclk;
2182	  uint32_t mclk_div;
2183	  int denominator;
2184	  int numerator;
2185	  uint32_t regval;
2186	  uint32_t freq_diff;
2187	  uint16_t bclk_div;
2188	
2189	  /* TODO: provide other clock support modes */
2190	
2191	  /* I2S module will using PLL_D2_CLK(160M) as source clock. */
2192	
2193	  sclk = I2S_LL_BASE_CLK;
2194	
2195	  /* fmclk = bck_div * fbclk = fsclk / (mclk_div + b / a)
2196	   * mclk_div is the I2S clock divider's integral value
2197	   * b is the fraction clock divider's numerator value
2198	   * a is the fraction clock divider's denominator value
2199	   */
2200	
2201	  if (priv->config->role == I2S_ROLE_MASTER)
2202	    {
2203	      /* Use data_width as slot width to match ESP-IDF standard config.
2204	       * ESP-IDF I2S_SLOT_BIT_WIDTH_AUTO = data_bit_width for Philips.
2205	       */
2206	
2207	      uint32_t slot_w = priv->data_width;
2208	
2209	      bclk = priv->rate * priv->config->total_slot * slot_w;
2210	      mclk = priv->mclk_freq;
2211	      bclk_div = mclk / bclk;
2212	
2213	      /* printf(">>> TDM8_TEST: total_slot=8 slot_width=16 bclk=%lu <<<\n", (unsigned long)bclk); */
2214	    }
2215	  else
2216	    {
2217	      /* For slave mode, mclk >= bclk * 8, so fix bclk_div to 2 first */
2218	
2219	      uint32_t slot_w = priv->data_width;
2220	
2221	      bclk_div = 8;
2222	      bclk = priv->rate * priv->config->total_slot * slot_w;
2223	      mclk = bclk * bclk_div;
2224	
2225	      /* printf(">>> TDM8_TEST: total_slot=8 slot_width=16 bclk=%lu <<<\n", (unsigned long)bclk); */
2226	    }
2227	
2228	  /* Calculate the nearest integer value of the I2S clock divider */
2229	
2230	  mclk_div = sclk / mclk;
2231	
2232	  i2sinfo("Clock division info: [sclk]%" PRIu32 " Hz [mdiv] %d "
2233	          "[mclk] %" PRIu32 " Hz [bdiv] %d [bclk] %" PRIu32 " Hz\n",
2234	          sclk, mclk_div, mclk, bclk_div, bclk);
2235	
2236	  /* printf(">>> I2S_CLK: sclk=%lu mdiv=%d mclk=%lu bdiv=%d bclk=%lu rate=%lu ws=%lu <<<\n",
2237	        (unsigned long)sclk, mclk_div, (unsigned long)mclk, bclk_div,
2238	        (unsigned long)bclk, (unsigned long)priv->rate,
2239	        (unsigned long)(bclk / (priv->config->total_slot * priv->data_width))); */
2240	
2241	  freq_diff = abs((int)sclk - (int)(mclk * mclk_div));
2242	
2243	  denominator = 1;
2244	  numerator = 0;
2245	
2246	  if (freq_diff)
2247	    {
2248	      float decimal = freq_diff / (float)mclk;
2249	
2250	      /* Carry bit if the decimal is greater than
2251	       * 1.0 - 1.0 / (63.0 * 2) = 125.0 / 126.0
2252	       */
2253	
2254	      if (decimal > 125.0f / 126.0f)
2255	        {
2256	          mclk_div++;
2257	        }
2258	      else
2259	        {
2260	          uint32_t min = UINT32_MAX;
2261	
2262	          for (int a = 2; a <= I2S_LL_MCLK_DIVIDER_MAX; a++)
2263	            {
2264	              int b = (int)(a * (freq_diff / (double)mclk) + 0.5);
2265	              int ma = freq_diff * a;
2266	              int mb = mclk * b;
2267	              if (ma == mb)
2268	                {
2269	                  denominator = a;
2270	                  numerator = b;
2271	                  break;
2272	                }
2273	
2274	              if (abs((mb - ma)) < min)
2275	                {
2276	                  denominator = a;
2277	                  numerator = b;
2278	                  min = abs(mb - ma);
2279	                }
2280	            }
2281	        }
2282	    }
2283	
2284	  i2sinfo("Clock register: [mclk] %" PRIu32 " Hz [numerator] %d "
2285	          "[denominator] %d\n", mclk, numerator, denominator);
2286	
2287	  /* Setup TX Clock */
2288	
2289	  regval = getreg32(I2S_TX_CLKM_CONF_REG(priv->config->port));
2290	  regval &= ~I2S_TX_CLKM_DIV_NUM_M;
2291	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_NUM, mclk_div);
2292	  putreg32(regval, I2S_TX_CLKM_CONF_REG(priv->config->port));
2293	
2294	  regval = getreg32(I2S_TX_CLKM_DIV_CONF_REG(priv->config->port));
2295	  regval &= ~(I2S_TX_CLKM_DIV_Z_M | I2S_TX_CLKM_DIV_Y_M |
2296	              I2S_TX_CLKM_DIV_X_M | I2S_TX_CLKM_DIV_YN1_M);
2297	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Z,
2298	                           numerator <= (denominator / 2) ?
2299	                           numerator : (denominator - numerator));
2300	
2301	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y,
2302	                           numerator <= (denominator / 2) ?
2303	                           (denominator % numerator) :
2304	                           (denominator % (denominator - numerator)));
2305	
2306	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X,
2307	                           numerator <= (denominator / 2) ?
2308	                           (int)(floor(denominator / numerator) - 1) :
2309	                           (int)(floor(denominator /
2310	                                       (denominator - numerator))-1));
2311	
2312	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_YN1,
2313	                           numerator <= (denominator / 2) ?
2314	                           0 : 1);
2315	  putreg32(regval, I2S_TX_CLKM_DIV_CONF_REG(priv->config->port));
2316	
2317	  /* Setup RX Clock */
2318	
2319	  regval = getreg32(I2S_RX_CLKM_CONF_REG(priv->config->port));
2320	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
2321	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
2322	  putreg32(regval, I2S_RX_CLKM_CONF_REG(priv->config->port));
2323	
2324	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(priv->config->port));
2325	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
2326	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
2327	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Z,
2328	                           numerator <= (denominator / 2) ?
2329	                           numerator : (denominator - numerator));
2330	
2331	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y,
2332	                           numerator <= (denominator / 2) ?
2333	                           (denominator % numerator) :
2334	                           (denominator % (denominator - numerator)));
2335	
2336	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_X,
2337	                           numerator <= (denominator / 2) ?
2338	                           (int)(floor(denominator / numerator) - 1) :
2339	                           (int)(floor(denominator /
2340	                                       (denominator - numerator))-1));
2341	
2342	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_YN1,
2343	                           numerator <= (denominator / 2) ?
2344	                           0 : 1);
2345	  putreg32(regval, I2S_RX_CLKM_DIV_CONF_REG(priv->config->port));
2346	
2347	  /* Set I2S TX bck div num
2348	   * Note: I2S_TX/RX_BCK_DIV_NUM cannot be 1
2349	   */
2350	
2351	#ifdef I2S_HAVE_TX
2352	  modifyreg32(I2S_TX_CONF1_REG(priv->config->port),
2353	              I2S_TX_BCK_DIV_NUM_M,
2354	              FIELD_TO_VALUE(I2S_TX_BCK_DIV_NUM, bclk_div - 1));
2355	
2356	  /* Set I2S_TX_UPDATE bit to update the configs.
2357	   * This bit is automatically cleared.
2358	   */
2359	
2360	  modifyreg32(I2S_TX_CONF_REG(priv->config->port),
2361	              0, I2S_TX_UPDATE);
2362	#endif /* I2S_HAVE_TX */
2363	
2364	#ifdef I2S_HAVE_RX
2365	  modifyreg32(I2S_RX_CONF1_REG(priv->config->port),
2366	              I2S_RX_BCK_DIV_NUM_M,
2367	              FIELD_TO_VALUE(I2S_RX_BCK_DIV_NUM, bclk_div - 1));
2368	
2369	  /* Set I2S_RX_UPDATE bit to update the configs.
2370	   * This bit is automatically cleared.
2371	   */
2372	
2373	  modifyreg32(I2S_RX_CONF_REG(priv->config->port),
2374	              0, I2S_RX_UPDATE);
2375	#endif /* I2S_HAVE_RX */
2376	
2377	  /* Returns the actual sample rate */
2378	
2379	  bclk = sclk / (float)((mclk_div + numerator / (float)denominator) *
2380	                        bclk_div);
2381	  {
2382	    uint32_t slot_w = priv->data_width;
2383	    rate = bclk / (float)(priv->config->total_slot * slot_w);
2384	  }
2385	
2386	  return rate;
2387	}
