2389	/****************************************************************************
2390	 * Name: i2s_tx_channel_start
2391	 *
2392	 * Description:
2393	 *   Start TX channel for the I2S port
2394	 *
2395	 * Input Parameters:
2396	 *   priv - Initialized I2S device structure.
2397	 *
2398	 * Returned Value:
2399	 *   None
2400	 *
2401	 ****************************************************************************/
2402	
2403	#ifdef I2S_HAVE_TX
2404	static void i2s_tx_channel_start(struct esp32s3_i2s_s *priv)
2405	{
2406	  if (priv->config->tx_en)
2407	    {
2408	      if (priv->tx_started)
2409	        {
2410	          i2swarn("TX channel of port %d was previously started\n",
2411	                  priv->config->port);
2412	          return;
2413	        }
2414	
2415	      /* Reset the DMA operation */
2416	
2417	      SET_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, priv->dma_channel,
2418	                       DMA_OUT_RST_CH0_M);
2419	      CLR_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, priv->dma_channel,
2420	                       DMA_OUT_RST_CH0_M);
2421	      CLR_GDMA_CH_BITS(DMA_OUT_CONF1_CH0_REG, priv->dma_channel,
2422	                       DMA_OUT_CHECK_OWNER_CH0);
2423	
2424	      /* Reset the TX channel */
2425	
2426	      modifyreg32(I2S_TX_CONF_REG(priv->config->port), 0, I2S_TX_RESET);
2427	      modifyreg32(I2S_TX_CONF_REG(priv->config->port), I2S_TX_RESET, 0);
2428	
2429	      /* Reset TX FIFO */
2430	
2431	      modifyreg32(I2S_TX_CONF_REG(priv->config->port), 0, I2S_TX_FIFO_RESET);
2432	      modifyreg32(I2S_TX_CONF_REG(priv->config->port), I2S_TX_FIFO_RESET, 0);
2433	
2434	      /* Clear I2S_TX_STOP_EN (default=1) so that BCK and WS signals
2435	       * keep running even when the TX FIFO is briefly empty between
2436	       * DMA buffer transitions. With the default (1), BCK/WS stop at
2437	       * every buffer boundary, causing the ES8311 codec to see a clock
2438	       * interruption and produce regular pop noise.
2439	       */
2440	
2441	      modifyreg32(I2S_TX_CONF_REG(priv->config->port), I2S_TX_STOP_EN, 0);
2442	
2443	      /* TX_RESET clears CONF1 registers to defaults.  Re-apply the
2444	       * data width and TDM slot configuration.
2445	       */
2446	
2447	      i2s_set_datawidth(priv);
2448	
2449	      /* Set I2S_RX_UPDATE bit to update the configs.
2450	       * This bit is automatically cleared.
2451	       */
2452	
2453	      modifyreg32(I2S_TX_CONF_REG(priv->config->port), 0, I2S_TX_UPDATE);
2454	
2455	      /* Enable DMA interrupt */
2456	
2457	      up_enable_irq(priv->tx_irq);
2458	
2459	      SET_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
2460	                       DMA_OUT_TOTAL_EOF_CH0_INT_ENA |
2461	                       DMA_OUT_DSCR_ERR_CH0_INT_ENA);
2462

740	    }
741	
742	  priv->mclk = I2S_GETMCLKFREQUENCY(priv->i2s);
743	  ret = 0;
744	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG02) & 0x07;
745	  regconfig |= (es8311_coeff_div[coeff_index].pre_div - 1) << 5;
746	
747	  datmp = 0;
748	  switch (es8311_coeff_div[coeff_index].pre_multi)
749	    {
750	      case 1:
751	        datmp = 0;
752	        break;
753	      case 2:
754	        datmp = 1;
755	        break;
756	      case 4:
757	        datmp = 2;
758	        break;
759	      case 8:
760	        datmp = 3;
761	        break;
762	      default:
763	        break;
764	    }
765	
766	  if (es8311_get_mclk_src() == ES8311_MCLK_FROM_SCLK_PIN)
767	    {
768	      datmp = 3;     /* DIG_MCLK = LRCK * 256 = BCLK * 8 */
769	    }
770	
771	  regconfig |= (datmp) << 3;
772	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG02, regconfig);
773	
774	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG05) & 0x00;
775	  regconfig |= (es8311_coeff_div[coeff_index].adc_div - 1) << 4;
776	  regconfig |= (es8311_coeff_div[coeff_index].dac_div - 1) << 0;
777	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG05, regconfig);
778	
779	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG03) & 0x80;
780	  regconfig |= es8311_coeff_div[coeff_index].fs_mode << 6;
781	  regconfig |= es8311_coeff_div[coeff_index].adc_osr << 0;
782	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG03, regconfig);
783	
784	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG04) & 0x80;
785	  regconfig |= es8311_coeff_div[coeff_index].dac_osr << 0;
786	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG04, regconfig);
787	
788	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG07) & 0xc0;
789	  regconfig |= es8311_coeff_div[coeff_index].lrck_h << 0;
790	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG07, regconfig);
791	
792	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG08) & 0x00;
793	  regconfig |= es8311_coeff_div[coeff_index].lrck_l << 0;
794	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG08, regconfig);
795	
796	  regconfig = es8311_readreg(priv, ES8311_CLK_MANAGER_REG06) & 0xe0;
797	  if (es8311_coeff_div[coeff_index].bclk_div < 19)
798	    {
799	      regconfig |= (es8311_coeff_div[coeff_index].bclk_div - 1) << 0;
800	    }
801	  else
802	    {
803	      regconfig |= (es8311_coeff_div[coeff_index].bclk_div) << 0;
804	    }
805	
806	  ret |= es8311_writereg(priv, ES8311_CLK_MANAGER_REG06, regconfig);
807	
808	  /* 诊断：定位慢速/倍速时 es8311 内部分频器是否配错 */
809	  syslog(LOG_INFO,
810	         "es8311 srate: coeff=%d rate=%u pre_div=%u pre_multi=%u "
811	         "dac_div=%u dac_osr=%u reg02=0x%02x reg04=0x%02x reg05=0x%02x\n",
812	         coeff_index, priv->samprate,
813	         es8311_coeff_div[coeff_index].pre_div,
814	         es8311_coeff_div[coeff_index].pre_multi,
815	         es8311_coeff_div[coeff_index].dac_div,
816	         es8311_coeff_div[coeff_index].dac_osr,
817	         es8311_readreg(priv, ES8311_CLK_MANAGER_REG02),
818	         es8311_readreg(priv, ES8311_CLK_MANAGER_REG04),
819	         es8311_readreg(priv, ES8311_CLK_MANAGER_REG05));
820	
821	  if (ret < 0)
822	    {
823	      auderr("Failed to set sample rate.\n");
824	      return -EIO;
825	    }
826	  else
827	    {
828	      audinfo("Sample rate set to: %d.\n", priv->samprate);
829	      return OK;
830	    }
831	}
