911	        caps->ac_channels = 1;
912	
913	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
914	          {
915	              /* Report supported input sample rates */
916	
917	              caps->ac_controls.hw[0] =
918	                AUDIO_SAMP_RATE_11K | AUDIO_SAMP_RATE_16K |
919	                AUDIO_SAMP_RATE_22K | AUDIO_SAMP_RATE_32K |
920	                AUDIO_SAMP_RATE_44K | AUDIO_SAMP_RATE_48K;
921	              break;
922	         }
923	
924	        break;
925	
926	      /* Provide capabilities of our FEATURE units */
927	
928	      case AUDIO_TYPE_FEATURE:
929	
930	        /* If the sub-type is UNDEF, then report the Feature Units we
931	         * support.
932	         */
933	
934	        if (caps->ac_subtype == AUDIO_FU_UNDEF)
935	          {
936	            /* Fill in the ac_controls section with the Feature Units we
937	             * have.
938	             */
939

670	 * Description:
671	 *  Sets the sample frequency for the codec ADC/DAC and the I2S driver.
672	 *
673	 * Input Parameters:
674	 *   priv - A reference to the driver state structure.
675	 *
676	 * Returned Value:
677	 *   Returns OK or a negated errno value on failure.
678	 *
679	 ****************************************************************************/
680	
681	static int es8311_setsamplerate(FAR struct es8311_dev_s *priv)
682	{
