2054	/****************************************************************************
2055	 * Name: i2s_set_datawidth
2056	 *
2057	 * Description:
2058	 *   Set the I2S TX/RX data width.
2059	 *
2060	 * Input Parameters:
2061	 *   priv - Initialized I2S device structure.
2062	 *
2063	 * Returned Value:
2064	 *   Returns the resulting data width
2065	 *
2066	 ****************************************************************************/
2067	
2068	static uint32_t i2s_set_datawidth(struct esp32s3_i2s_s *priv)
2069	{
2070	#ifdef I2S_HAVE_TX
2071	  if (priv->config->tx_en)
2072	    {
2073	      uint32_t slot_width = priv->data_width;
2074	
2075	      modifyreg32(I2S_TX_CONF1_REG(priv->config->port),
2076	                  I2S_TX_BITS_MOD_M, FIELD_TO_VALUE(I2S_TX_BITS_MOD,
2077	                  priv->data_width - 1));
2078	
2079	      modifyreg32(I2S_TX_CONF1_REG(priv->config->port),
2080	                  I2S_TX_TDM_CHAN_BITS_M,
2081	                  FIELD_TO_VALUE(I2S_TX_TDM_CHAN_BITS,
2082	                  slot_width - 1));
2083	
2084	      modifyreg32(I2S_TX_CONF1_REG(priv->config->port),
2085	                  I2S_TX_HALF_SAMPLE_BITS_M,
2086	                  FIELD_TO_VALUE(I2S_TX_HALF_SAMPLE_BITS,
2087	                  slot_width - 1));
2088	
2089	      if (priv->config->audio_std_mode == I2S_TDM_PCM)
2090	        {
2091	          modifyreg32(I2S_TX_CONF1_REG(priv->config->port),
2092	                      I2S_TX_TDM_WS_WIDTH_M,
2093	                      FIELD_TO_VALUE(I2S_TX_TDM_WS_WIDTH, 1));
2094	        }
2095	      else
2096	        {
2097	          modifyreg32(I2S_TX_CONF1_REG(priv->config->port),
2098	                      I2S_TX_TDM_WS_WIDTH_M,
2099	                      FIELD_TO_VALUE(I2S_TX_TDM_WS_WIDTH,
2100	                      slot_width - 1));
2101	        }
2102	
2103	      /* Set I2S_TX_UPDATE bit to update configs. Cleared automatically */
2104	
2105	      modifyreg32(I2S_TX_CONF_REG(priv->config->port),
2106	                  0, I2S_TX_UPDATE);
2107	    }
2108	#endif /* I2S_HAVE_TX */
2109	
2110	#ifdef I2S_HAVE_RX
2111	  if (priv->config->rx_en)
2112	    {
2113	      /* In Philips (I2S) mode, use data_width as slot width to match
2114	       * the standard I2S timing expected by codecs like ES7210.
2115	       * ESP-IDF uses I2S_SLOT_BIT_WIDTH_AUTO which equals data_width.
2116	       * For 16-bit data: BCLK = Fs * 2 * 16 = 1.536MHz (not 3.072MHz).
2117	       * This gives MCLK/BCLK = 8 which ES7210 expects.
2118	       */
2119	
2120	      uint32_t slot_width = priv->data_width;
2121	
2122	      /* printf(">>> I2S_SET_DATAWIDTH_RX: data_width=%d slot_width=%d "
2123	             "conf1_before=0x%lx <<<\n",
2124	             priv->data_width, slot_width,
2125	             (unsigned long)getreg32(I2S_RX_CONF1_REG(priv->config->port))); */
2126	
2127	      /* Use putreg32 to write all RX_CONF1 fields at once.
2128	       * The shadow register mechanism causes consecutive
2129	       * modifyreg32 calls to overwrite previous field settings.
2130	       */
2131	
2132	      uint32_t rx_conf1 = getreg32(I2S_RX_CONF1_REG(priv->config->port));
2133	      rx_conf1 &= ~(I2S_RX_BITS_MOD_M | I2S_RX_TDM_CHAN_BITS_M |
2134	                     I2S_RX_HALF_SAMPLE_BITS_M | I2S_RX_TDM_WS_WIDTH_M |
2135	                     I2S_RX_MSB_SHIFT_M);
2136	
2137	      rx_conf1 |= FIELD_TO_VALUE(I2S_RX_BITS_MOD, priv->data_width - 1);
2138	      rx_conf1 |= FIELD_TO_VALUE(I2S_RX_TDM_CHAN_BITS, slot_width - 1);
2139	      rx_conf1 |= FIELD_TO_VALUE(I2S_RX_HALF_SAMPLE_BITS, slot_width - 1);
2140	
2141	      if (priv->config->audio_std_mode == I2S_TDM_PCM)
2142	        {
2143	          rx_conf1 |= FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH, 1);
2144	        }
2145	      else
2146	        {
2147	          rx_conf1 |= FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH,
2148	                      slot_width - 1);
2149	          rx_conf1 |= I2S_RX_MSB_SHIFT;
2150	        }
2151	
2152	      putreg32(rx_conf1, I2S_RX_CONF1_REG(priv->config->port));
2153	
2154	      /* printf(">>> I2S_SET_DATAWIDTH_RX: conf1_after=0x%lx <<<\n",
2155	             (unsigned long)getreg32(I2S_RX_CONF1_REG(priv->config->port))); */
2156	    }
2157	#endif /* I2S_HAVE_RX */
2158	
2159	  return priv->data_width;
2160	}
