940	
941	  apb = bfcontainer->apb;
942	  outlink = bfcontainer->dma_link;
943	
944	  /* Get the transfer information, accounting for any data offset */
945	
946	  const apb_samp_t bytes_per_sample = priv->data_width / 8;
947	  samp = &apb->samp[apb->curbyte];
948	  samp_size = (apb->nbytes - apb->curbyte) + priv->tx.carry.bytes;
949	  carry_size = samp_size % bytes_per_sample;
950	
951	  /* Point DMA directly at the audio buffer to eliminate calloc + memcpy
952	   * overhead. The calloc (32KB zeroing) + memcpy (32KB copy) + flush_dcache
953	   * cycle generates ~128KB of PSRAM access that competes with the GDMA
954	   * for SPI bus bandwidth. When the GDMA is starved, the I2S TX FIFO
955	   * underruns and outputs zeros, causing a click/pop at every buffer
956	   * boundary (~0.2s at 44.1kHz).
957	   *
958	   * By pointing the DMA directly at apb->samp, we reduce PSRAM access
959	   * to just the flush_dcache (32KB write-back), which the GDMA can
960	   * tolerate without underrunning.
961	   *
962	   * The carry mechanism (for non-sample-aligned buffers) is preserved
963	   * as a fallback.
964	   */
965	
966	  if (priv->tx.carry.bytes == 0 && carry_size == 0)
967	    {
968	      /* Common case: no carry needed, buffer is sample-aligned.
969	       * Point DMA directly at the audio buffer.
970	       */
971	
972	      bfcontainer->buf = NULL;
973	      priv->tx.carry.bytes = 0;
974	
975	      /* Flush D-Cache so GDMA can read the audio data from PSRAM. */
976	
977	      up_flush_dcache((uintptr_t)samp,
978	                      (uintptr_t)samp + samp_size);
979	
980	      bytes_queued = esp32s3_dma_setup(outlink, I2S_DMADESC_NUM,
