117	int audio_playback_drain(audio_playback_t* pb)
118	{
119	    if (!pb || !pb->player) {
120	        return -EINVAL;
121	    }
122	
123	    /* Estimate playback duration from total bytes written.
124	     * bytes_per_frame = (bits/8) * channels = 4 for 16-bit stereo.
125	     * sample_rate = 24000.  Duration = total_written / (sample_rate * bytes_per_frame).
126	     * Add 200ms safety margin for I2S DMA drain. */
127	    if (pb->total_written > 0 && pb->bytes_per_frame > 0) {
128	        uint32_t sample_rate = AGENT_TTS_WS_SAMPLE_RATE;  /* 24000 */
129	        uint32_t duration_ms = (uint32_t)(pb->total_written * 1000ULL
130	            / (sample_rate * (uint32_t)pb->bytes_per_frame));
131	        uint32_t wait_ms = duration_ms + 200;
132	        if (wait_ms > 30000) wait_ms = 30000;
133	        usleep(wait_ms * 1000);
134	    } else {
135	        /* No data written — short wait for any buffered silence */
136	        usleep(200 * 1000);
137	    }
138	    return 0;
139	}
