129	#ifdef CONFIG_AI_AGENT_NET_RPMSG
130	static volatile bool g_net_services_started = false;
131	
132	static void net_state_change_cb(net_state_t state, void* arg)
133	{
134	    (void)arg;
135	    if (state == NET_STATE_CONNECTED && !g_net_services_started) {
136	        syslog(LOG_INFO, "[%s] Network recovered, starting services\n", TAG);
137	#ifdef CONFIG_AI_AGENT_FEISHU
138	        feishu_bot_start();
139	#endif
140	        agent_loop_start();
141	        ws_server_start();
142	#ifdef CONFIG_AI_AGENT_NODE
143	        node_client_start();
144	#endif
145	#ifdef CONFIG_AI_AGENT_MQTT
146	        mqtt_channel_start();
147	#endif
148	#ifdef CONFIG_AI_AGENT_WEIXIN
149	        weixin_channel_start();
150	#endif
151	        g_net_services_started = true;
152	    } else if (state == NET_STATE_DISCONNECTED) {
153	        syslog(LOG_WARNING,
154	            "[%s] Network lost, services may be affected\n", TAG);
155	        /* Services will handle disconnection via their own error paths.
156	         * We just log the event here. g_net_services_started stays true
157	         * so we don't re-start services that are already running. */
158	    }
159	}
160	#endif
