162	/**
163	 * Runs in a background thread: waits for network, then starts all
164	 * network-dependent services. Main thread is NOT blocked.
165	 */
166	static void* network_watch_task(void* arg)
167	{
168	    (void)arg;
169	    syslog(LOG_INFO, "[%s] Network watcher started\n", TAG);
170	
171	    network_wifi_reconnect();
172	
173	    if (network_wait_connected(30000) == OK) {
174	        syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, network_get_ip());
175	
176	#if AGENT_SKILL_SYNC_ENABLED
177	        /* Sync skills from Bitable before starting agent loop */
178	        if (skill_sync_from_bitable() != OK) {
179	            syslog(LOG_WARNING, "[%s] Bitable skill sync failed, using local skills\n", TAG);
180	        }
181	#endif
182	
183	#ifdef CONFIG_AI_AGENT_FEISHU
184	        if (feishu_bot_start() != OK)
185	            syslog(LOG_WARNING, "[%s] feishu_bot_start failed\n", TAG);
186	#endif
187	        if (agent_loop_start() != OK)
188	            syslog(LOG_WARNING, "[%s] agent_loop_start failed\n", TAG);
189	        if (ws_server_start() != OK)
190	            syslog(LOG_WARNING, "[%s] ws_server_start failed\n", TAG);
191	#ifdef CONFIG_AI_AGENT_NODE
192	        if (node_client_start() != OK)
193	            syslog(LOG_WARNING, "[%s] node_client_start failed\n", TAG);
194	#endif
195	#ifdef CONFIG_AI_AGENT_MQTT
196	        if (mqtt_channel_start() != OK)
197	            syslog(LOG_WARNING, "[%s] mqtt_channel_start failed\n", TAG);
198	#endif
199	#ifdef CONFIG_AI_AGENT_WEIXIN
200	        if (weixin_channel_start() != OK)
201	            syslog(LOG_WARNING, "[%s] weixin_channel_start failed\n", TAG);
202	#endif
203	
204	        syslog(LOG_INFO, "[%s] All network services started!\n", TAG);
205	
206	        /* Auto mode: voice_channel_start_wake() is called externally
207	         * by the launcher after both agent init and WiFi are confirmed
208	         * ready. This avoids race conditions where the conversation
209	         * thread starts before the network is stable. */
210	
211	#ifdef CONFIG_AI_AGENT_NET_RPMSG
212	        g_net_services_started = true;
213	#endif
214	    } else {
215	        syslog(LOG_WARNING, "[%s] Network timeout — net services not started.\n", TAG);
216	        syslog(LOG_WARNING, "[%s] Use 'config_show' / 'set_*' CLI commands to configure.\n", TAG);
217	        /* Play no-network alert audio (highest priority) */
218	        tool_system_alert_play(16, 0);
219	    }
220	
221	#ifdef CONFIG_AI_AGENT_NET_RPMSG
222	    /* Register listener for network state changes — auto-restart services on reconnect */
223	    network_register_listener(net_state_change_cb, NULL);
224	
225	    /* Keep thread alive to handle reconnection events */
226	    while (!g_shutdown_requested) {
227	        sleep(1);
228	    }
229	#endif
230	
231	    return NULL;
232	}
