234	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
235	/* -- Quickapp mqueue IPC (cross-process bridge) --------------- */
236	
237	#include <mqueue.h>
238	#include <fcntl.h>
239	#include <errno.h>
240	
241	#define VELACLAW_MQ_QAPP_IN   "/velaclaw_qapp_in"
242	#define VELACLAW_MQ_QAPP_OUT  "/velaclaw_qapp_out"
243	#define VELACLAW_MQ_MSG_SIZE  4096
244	#define VELACLAW_MQ_MAX_MSGS  4
245	
246	/**
247	 * Reads requests from the quickapp process via POSIX mqueue and feeds
248	 * them into the local message_bus inbound queue.
249	 */
250	static void *quickapp_mq_listener_task(void *arg)
251	{
252	    (void)arg;
253	    syslog(LOG_INFO, "[%s] Quickapp mqueue listener started\n", TAG);
254	
255	    struct mq_attr attr = {
256	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
257	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
258	    };
259	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_RDONLY | O_CREAT, 0666, &attr);
260	    if (mq == (mqd_t)-1) {
261	        syslog(LOG_ERR, "[%s] Failed to open quickapp inbound mqueue: %d\n", TAG, errno);
262	        return NULL;
263	    }
264	
265	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
266	    if (!buf) {
267	        syslog(LOG_ERR, "[%s] Failed to allocate mqueue recv buffer\n", TAG);
268	        mq_close(mq);
269	        return NULL;
270	    }
271	
272	    while (1) {
273	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
274	        if (n < 0) {
275	            if (errno == EINTR) continue;
276	            syslog(LOG_ERR, "[%s] mq_receive failed: %d\n", TAG, errno);
277	            break;
278	        }
279	        if (n >= (ssize_t)VELACLAW_MQ_MSG_SIZE) {
280	            n = VELACLAW_MQ_MSG_SIZE - 1;
281	        }
282	        buf[n] = '\0';
283	
284	        /* Message format: "chat_id\nquery" */
285	        char *sep = strchr(buf, '\n');
286	        if (!sep) {
287	            syslog(LOG_WARNING, "[%s] Malformed quickapp message\n", TAG);
288	            continue;
289	        }
290	        *sep = '\0';
291	        const char *chat_id = buf;
292	        const char *query = sep + 1;
293	
294	        syslog(LOG_INFO, "[%s] Quickapp request: chat_id=%s query=%.40s\n",
295	               TAG, chat_id, query);
296	
297	        agent_msg_t msg = {0};
298	        strncpy(msg.channel, AGENT_CHAN_QUICKAPP, sizeof(msg.channel) - 1);
299	        strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
300	        msg.content = strdup(query);
301	        if (msg.content) {
302	            message_bus_push_inbound(&msg);
303	        }
304	    }
305	
306	    free(buf);
307	    mq_close(mq);
308	    return NULL;
309	}
310	
311	/**
312	 * Send a reply to the quickapp process via the outbound mqueue.
313	 * Called from the outbound dispatch thread in the agent process.
314	 */
315	static void quickapp_mq_dispatch(const char *chat_id, const char *content)
316	{
317	    struct mq_attr attr = {
318	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
319	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
320	    };
321	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_WRONLY | O_CREAT, 0666, &attr);
322	    if (mq == (mqd_t)-1) {
323	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_open failed: %d\n", TAG, errno);
324	        return;
325	    }
326	
327	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
328	    if (!buf) {
329	        mq_close(mq);
330	        return;
331	    }
332	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, content);
333	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
334	        len = VELACLAW_MQ_MSG_SIZE - 1;
335	        buf[len] = '\0';
336	    }
337	
338	    if (mq_send(mq, buf, len + 1, 0) != 0) {
339	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_send failed: %d\n", TAG, errno);
340	    } else {
341	        syslog(LOG_INFO, "[%s] quickapp dispatch: reply sent chat_id=%s\n", TAG, chat_id);
342	    }
343	    free(buf);
344	    mq_close(mq);
345	}
346	#endif /* CONFIG_FEATURE_SYSTEM_VELACLAW */
