348	/* ── Outbound dispatch ────────────────────────────────────────── */
349	
350	/**
351	 * Reads messages from the outbound queue and dispatches them to the
352	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
353	 */
354	static void* outbound_dispatch_task(void* arg)
355	{
356	    (void)arg;
357	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
358	
359	    while (!g_shutdown_requested) {
360	        agent_msg_t msg;
361	        if (message_bus_pop_outbound(&msg, 1000) != OK)
362	            continue;
363	        msg.channel[sizeof(msg.channel) - 1] = '\0';
364	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
365	
366	        if (!msg.content) {
367	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
368	            continue;
369	        }
370	
371	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
372	
373	        /* Let registered taps intercept before normal dispatch */
374	        if (mbus_tap_try_deliver(&msg)) {
375	            free(msg.content);
376	            continue;
377	        }
378	
379	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
380	            bool delivered = false;
381	#ifdef CONFIG_AI_AGENT_FEISHU
382	            const char* app_id = feishu_get_app_id();
383	            if (app_id && app_id[0] != '\0') {
384	                feishu_send_message(msg.chat_id, msg.content);
385	                delivered = true;
386	            }
387	#endif
388	#ifdef CONFIG_AI_AGENT_NODE
389	            if (!delivered) {
390	                delivered = node_client_send_chat_message(
391	                    msg.channel, msg.chat_id, msg.content) == OK;
392	            }
393	#endif
394	            if (!delivered) {
395	                syslog(LOG_WARNING,
396	                    "[%s] Feishu message dropped: no local config "
397	                    "and no gateway\n",
398	                    TAG);
399	            }
400	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
401	            ws_server_send(msg.chat_id, msg.content);
402	#ifdef CONFIG_AI_AGENT_MQTT
403	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
404	            mqtt_channel_send(msg.chat_id, msg.content);
405	#endif
406	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
407	            /* TTS already handled in dispatch_response (agent_loop.c).
408	             * Voice channel outbound dispatch is a no-op — the response
409	             * was already spoken before being enqueued. */
410	#ifdef CONFIG_AI_AGENT_LVGL_UI
411	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
412	            int uret = lvgl_ui_channel_send(msg.content);
413	            if (uret != 0) {
414	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
415	            }
416	#endif
417	#ifdef CONFIG_AI_AGENT_WEIXIN
418	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
419	            /* chat_id format: "from_user_id|context_token" */
420	            char uid[64] = "";
421	            const char* ctx = "";
422	            char* sep = strchr(msg.chat_id, '|');
423	            if (sep) {
424	                size_t ulen = (size_t)(sep - msg.chat_id);
425	                if (ulen >= sizeof(uid))
426	                    ulen = sizeof(uid) - 1;
427	                memcpy(uid, msg.chat_id, ulen);
428	                uid[ulen] = '\0';
429	                ctx = sep + 1;
430	            } else {
431	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
432	            }
433	            weixin_channel_send(uid, ctx, msg.content);
434	#endif
435	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
436	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
437	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
438	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
439	            quickapp_mq_dispatch(msg.chat_id, msg.content);
440	#endif
441	        } else if (strcmp(msg.channel, "cli") == 0) {
442	            pthread_mutex_lock(&g_stdout_lock);
443	            syslog("\n[Agent]: %s\nvela> ", msg.content);
444	            fflush(stdout);
445	            pthread_mutex_unlock(&g_stdout_lock);
446	            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
447	        } else {
448	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
449	        }
450	
451	        free(msg.content);
452	    }
453	
454	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
455	    return NULL;
456	}
