460	/* ── Startup timing helpers ───────────────────────────────────── */
461	
462	static inline long boot_ms(struct timespec* t0)
463	{
464	    struct timespec now;
465	    clock_gettime(CLOCK_MONOTONIC, &now);
466	    return (long)((now.tv_sec - t0->tv_sec) * 1000L + (now.tv_nsec - t0->tv_nsec) / 1000000L);
467	}
468	
469	#define BOOT_LOG(t0, phase, msg) \
470	    syslog(LOG_INFO, "[%s] [boot +%ldms] " phase ": " msg "\n", TAG, boot_ms(t0))
471	
472	#define BOOT_LOG_RC(t0, phase, msg, rc) \
473	    syslog((rc) == OK ? LOG_INFO : LOG_WARNING, \
474	        "[%s] [boot +%ldms] " phase ": " msg " (rc=%d)\n", TAG, boot_ms(t0), (rc))
475	
476	int ai_agent_main(int argc, char* argv[])
477	{
478	    /* "auto" argv: launched from launcher at boot — no CLI thread,
479	     * auto wake-word listening after network is up. */
480	    g_auto_voice = false;
481	    for (int i = 1; i < argc; i++) {
482	        if (argv[i] && strcmp(argv[i], "auto") == 0) {
483	            g_auto_voice = true;
484	        }
485	    }
486	
487	    g_shutdown_requested = false;
488	    g_agent_running = true;
489	
490	    /* Reset the voice backend registries up front: on a runtime UI-mode
491	     * switch the agent is re-launched via task_create() and these statics
492	     * persist, so without this the launcher's deferred wake-start sees
493	     * voice_channel_is_ready()==true immediately and starts wake-listening
494	     * before this instance re-registers its backends. */
495	    voice_channel_reset_backends();
496	
497	    struct timespec t0;
498	    clock_gettime(CLOCK_MONOTONIC, &t0);
499	
500	    syslog(LOG_INFO, "[%s] AI Agent - Vela AI Agent starting (build: %s)\n",
501	        TAG, AGENT_BUILD_VERSION);
502	
503	    /* ── Phase 0: Timezone ──────────────────────────────────── */
504	    /* Set TZ before any time calls so localtime_r returns CST+8.
505	     * NuttX with CONFIG_LIBC_LOCALTIME+CONFIG_LIBC_ZONEINFO supports
506	     * both POSIX ("CST-8") and zoneinfo ("Asia/Shanghai") formats.
507	     *
508	     * Idempotent: on a runtime UI-mode switch the agent is re-launched
509	     * (fresh ai_agent_main), and blindly re-applying TZ+tzset() made the
510	     * displayed clock jump back 8h (local 18:38 → UTC 10:38).  Only touch
511	     * it when the current TZ differs. */
512	    const char* cur_tz = getenv("TZ");
513	    if (cur_tz == NULL || strcmp(cur_tz, AGENT_TIMEZONE) != 0) {
514	        setenv("TZ", AGENT_TIMEZONE, 1);
515	#ifdef CONFIG_LIBC_LOCALTIME
516	        tzset();
517	#endif
518	    }
519	    BOOT_LOG(&t0, "P0", "timezone set");
520	
521	    /* ── Phase 0: Storage Bootstrapping (Auto-mount & Mkdir) ── */
522	
523	    struct stat st;
524	    if (stat("/data", &st) != 0) {
525	        syslog(LOG_INFO, "[%s] Mounting /data as tmpfs for simulation...\n", TAG);
526	        mount(NULL, "/data", "tmpfs", 0, NULL);
527	    }
528	
529	    /* Ensure directory structure exists (use configured AGENT_DATA_DIR) */
530	    mkdir(AGENT_DATA_DIR, 0755);
531	    mkdir(AGENT_CONFIG_DIR, 0755);
532	    mkdir(AGENT_MEMORY_DIR, 0755);
533	    mkdir(AGENT_SESSION_DIR, 0755);
534	    mkdir(AGENT_SKILLS_DIR, 0755);
535	
536	    /* Restore persistent config from SPI Flash (survives reboot).
537	     * Only config.json is persisted — skills/memory/sessions are
538	     * rebuilt at runtime on fast tmpfs. */
539	    {
540	        struct stat ps;
541	        if (stat(AGENT_PERSIST_CONFIG_FILE, &ps) == 0 && ps.st_size > 0) {
542	            /* Copy SPI Flash → tmpfs */
543	            char buf[1024];
544	            int src = open(AGENT_PERSIST_CONFIG_FILE, O_RDONLY);
545	            if (src >= 0) {
546	                int dst = open(AGENT_CONFIG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
547	                if (dst >= 0) {
548	                    ssize_t n;
549	                    while ((n = read(src, buf, sizeof(buf))) > 0) {
550	                        write(dst, buf, (size_t)n);
551	                    }
552	                    close(dst);
553	                }
554	                close(src);
555	                syslog(LOG_INFO, "[%s] Restored config from %s\n",
556	                    TAG, AGENT_PERSIST_CONFIG_FILE);
557	            }
558	        } else {
559	            /* Ensure SPI Flash persist dir exists for later writes */
560	            mkdir("/mnt/spif/ai_agent", 0755);
561	            mkdir(AGENT_PERSIST_CONFIG_DIR, 0755);
562	        }
563	    }
564	    BOOT_LOG(&t0, "P0", "storage ready");
565	
566	    /* Memory info */
567	    {
568	        struct mallinfo mi = mallinfo();
569	        syslog(LOG_INFO, "[%s] [boot +%ldms] heap: arena=%d free=%d used=%d\n",
