120	/**
121	 * @brief 后台拉起 ai_agent 任务（auto 模式：无 CLI，网络就绪后自动开启关键字唤醒）
122	 *
123	 * FLAT build 下 watch 与 ai_agent 同镜像，直接链接 ai_agent_main。
124	 * task_create 非阻塞，不影响 LVGL 主线程。
125	 */
126	static void agent_autostart(void)
127	{
128	  extern int ai_agent_main(int argc, char *argv[]);
129	
130	  if (g_agent_started)
131	    {
132	      return;
133	    }
134	  g_agent_started = true;
135	
136	  /* 注册唤醒词回调 + 空闲超时回调 + LVGL 轮询定时器 */
137	  voice_channel_set_wake_notify(on_wake_detected);
138	  voice_channel_set_idle_timeout_cb(on_idle_timeout);
139	  lv_timer_create(idle_timeout_poll_cb, 2000, NULL);
140	
141	  static char *agent_argv[] = { "auto", NULL };
142	  int pid = task_create("ai_agent", AGENT_TASK_PRIORITY,
143	                        AGENT_TASK_STACKSIZE, ai_agent_main, agent_argv);
144	  if (pid < 0)
145	    {
146	      WATCH_DBG_LOG("[LAUNCHER] ERROR: ai_agent task_create failed: %d", pid);
147	    }
148	  else
149	    {
150	      WATCH_DBG_LOG("[LAUNCHER] ai_agent started (pid=%d, auto mode)", pid);
151	    }
152	}
