259	/**
260	 * @brief 切换到下一个状态
261	 */
262	static void goto_next_state(void)
263	{
264	  switch (current_state)
265	    {
266	      case STATE_INIT:
267	        /* 切换到显示logo状态 */
268	        current_state = STATE_SHOW_LOGO;
269	
270	        /* 尽早读取UI模式，选择对应的开机logo */
271	        g_boot_ui_mode = ui_mode_load();
272	        ui_mode_set_current(g_boot_ui_mode);
273	        WATCH_DBG_LOG("[LAUNCHER] Boot UI mode: %d (0=expression, 1=watch)",
274	                      (int)g_boot_ui_mode);
275	
276	        /* 恢复上次持久化的音量（/mnt/spif/volume.json），
277	         * 避免重启后回退到板级默认值 */
278	        watch_volume_restore();
279	
280	        if (current_obj != NULL)
281	          {
282	            lv_obj_del(current_obj);
283	          }
284	
285	        if (g_boot_ui_mode == UI_MODE_WATCH)
286	          {
287	            current_obj = watch_boot_logo_init(content_area);
288	          }
289	        else
290	          {
291	            current_obj = boot_logo_init(content_area);
292	          }
293	        lv_task_handler();
294	
295	        /* 周期性检测logo GIF是否播完，播完立即切换（最长等待 LOGO_DISPLAY_TIME） */
296	        logo_wait_ms = 0;
297	        lv_timer_create(logo_check_timer_cb, LOGO_CHECK_PERIOD_MS, NULL);
298	        break;
299	
300	      case STATE_SHOW_LOGO:
301	        /* 切换到显示动画状态 */
302	        current_state = STATE_SHOW_ANIM;
303	
304	        /* 销毁logo并显示动画（根据UI模式选择对应的动画） */
305	        if (g_boot_ui_mode == UI_MODE_WATCH)
306	          {
307	            watch_boot_logo_deinit(current_obj);
308	            current_obj = watch_boot_animation_init(content_area);
309	          }
310	        else
311	          {
312	            boot_logo_deinit(current_obj);
313	            current_obj = boot_animation_init(content_area);
314	          }
315	        lv_task_handler();
316	
317	        /* 动画播放期间后台拉起 ai_agent（仅表情UI模式需要）
318	         * 手表UI模式不需要 ai_agent，跳过以加快开机速度 */
319	        if (g_boot_ui_mode == UI_MODE_EXPRESSION)
320	          {
321	            agent_autostart();
322	          }
323	
324	        /* 周期性检测动画是否播完，播完立即切换（最长等待 ANIMATION_DISPLAY_TIME） */
325	        anim_wait_ms = 0;
326	        lv_timer_create(anim_check_timer_cb, ANIM_CHECK_PERIOD_MS, NULL);
327	        break;
328	
329	      case STATE_SHOW_ANIM:
330	        /* 动画播放完成，切换到主界面 */
331	        current_state = STATE_SHOW_CLOCK;
332	
333	        /* 销毁动画（根据UI模式选择对应的销毁函数） */
334	        if (g_boot_ui_mode == UI_MODE_WATCH)
335	          {
336	            watch_boot_animation_deinit(current_obj);
337	          }
338	        else
339	          {
340	            boot_animation_deinit(current_obj);
341	          }
342	        current_obj = NULL;
343	
344	        /* 根据UI模式进入对应的主界面 */
345	        WATCH_DBG_LOG("[LAUNCHER] Entering UI mode: %d (0=expression, 1=watch)",
346	                      (int)g_boot_ui_mode);
347	
348	        if (g_boot_ui_mode == UI_MODE_WATCH)
349	          {
350	            /* 切换到 vendor watch UI */
351	            watch_switch_to_watch_app(content_area);
352	          }
353	        else
354	          {
355	            /* 默认：表情页面 */
356	            current_obj = (lv_obj_t *)watch_expression_page_init(
357	              content_area);
358	          }
359	
360	        /* 启动电池电量周期监控：开机立即检测一次，之后每60秒检测，
361	         * 电量低于20%时播报低电量语音（watch_battery_check_start 内部
362	         * 有重复调用保护） */
363	        watch_battery_check_start();
364	
365	        /* 仅表情UI模式启动延迟唤醒定时器（手表UI不需要语音唤醒） */
366	        if (g_boot_ui_mode == UI_MODE_EXPRESSION)
367	          {
368	            s_wake_timer = lv_timer_create(deferred_wake_start_timer_cb, 1000, NULL);
369	          }
370	
371	        lv_task_handler();
372	        break;
373	
374	      case STATE_SHOW_CLOCK:
375	        /* 手表界面持续运行，进入完成状态 */
376	        current_state = STATE_DONE;
377	        break;
378	
379	      default:
380	        break;
381	    }
382	}
