384	/**
385	 * @brief 动画播放完成检测定时器回调
386	 *
387	 * GIF播完最后一帧（boot_animation_is_finished）后立即切换到表情页面；
388	 * 超过 ANIMATION_DISPLAY_TIME 未播完则强制切换，避免一直停留在动画页。
389	 */
390	static void anim_check_timer_cb(lv_timer_t *timer)
391	{
392	  anim_wait_ms += ANIM_CHECK_PERIOD_MS;
393	
394	  /* 根据UI模式检查对应的动画是否播放完成 */
395	  bool finished = (g_boot_ui_mode == UI_MODE_WATCH)
396	    ? watch_boot_animation_is_finished()
397	    : boot_animation_is_finished();
398	
399	  if (finished || anim_wait_ms >= ANIMATION_DISPLAY_TIME)
400	    {
401	      lv_timer_del(timer);
402	      goto_next_state();
403	    }
404	}
405	
406	/**
407	 * @brief logo播放完成检测定时器回调
408	 *
409	 * GIF播完最后一帧（boot_logo_is_finished）后立即切换到动画页面；
410	 * 超过 LOGO_DISPLAY_TIME 未播完则强制切换，避免一直停留在logo页。
411	 */
412	static void logo_check_timer_cb(lv_timer_t *timer)
413	{
414	  logo_wait_ms += LOGO_CHECK_PERIOD_MS;
415	
416	  /* 根据UI模式检查对应的logo是否播放完成 */
417	  bool finished = (g_boot_ui_mode == UI_MODE_WATCH)
418	    ? watch_boot_logo_is_finished()
419	    : boot_logo_is_finished();
420	
421	  if (finished || logo_wait_ms >= LOGO_DISPLAY_TIME)
422	    {
423	      lv_timer_del(timer);
424	      goto_next_state();
425	    }
426	}
