94	static void goto_next_state(void)
95	{
96	  switch (current_state)
97	    {
98	      case STATE_INIT:
99	        /* 切换到显示logo状态 */
100	        current_state = STATE_SHOW_LOGO;
101	        if (current_obj != NULL)
102	          {
103	            lv_obj_del(current_obj);
104	          }
105	        current_obj = boot_logo_init(content_area);
106	        lv_task_handler();
107	        
108	        lv_timer_t *timer1 = lv_timer_create(state_timer_cb, LOGO_DISPLAY_TIME, NULL);
109	        lv_timer_set_repeat_count(timer1, 1);
110	        break;
111	
112	      case STATE_SHOW_LOGO:
113	        /* 切换到显示动画状态 */
114	        current_state = STATE_SHOW_ANIM;
115	
116	        /* 销毁logo并显示动画 */
117	        boot_logo_deinit(current_obj);
118	        LAUNCHER_LOG("boot_animation init, start load power anim: %p", current_obj);
119	        current_obj = boot_animation_init(content_area);
120	        lv_task_handler();
121	        
122	        /* 设置动画显示时间 */
123	        lv_timer_t *timer2 = lv_timer_create(state_timer_cb, ANIMATION_DISPLAY_TIME, NULL);
124	        lv_timer_set_repeat_count(timer2, 1);
125	        break;
126	
127	      case STATE_SHOW_ANIM:
128	        /* 切换到显示时钟状态 */
129	        current_state = STATE_SHOW_CLOCK;
130	        LAUNCHER_LOG("destory power anim, start dial init");
131	
132	        /* 销毁动画并显示时钟 */
133	        boot_animation_deinit(current_obj);
134	        current_obj = dial_init(content_area);
135	        lv_task_handler();
136	        alarm_service_init();
137	        pm_stay(PM_IDLE_DOMAIN, PM_NORMAL);
138	        display_set_timeout(10);
139	        ft3168_display_timeout_setup();
140	        LAUNCHER_LOG("dial init complete: %p", current_obj);
141	
142	        /* 启动充电状态检测定时器 (1秒检测一次) */
143	        if (charging_timer == NULL) {
144	            // charging_timer = lv_timer_create(charging_monitor_cb, 1000, NULL);
145	            LAUNCHER_LOG("[CHARGE] Charging monitor timer started");
146	        }
147	
148	        /* 读取抬腕亮屏配置 */
149	        wrist_raise_load_config();
150	
151	        /* 启动传感器监控定时器（抬腕+摔倒统一检测） */
152	        sensor_wrist_raise_timer_start();
153	
154	        break;
155	
156	      default:
157	        /* 其他状态不处理 */
158	        break;
159	    }
160	}
