287	/**
288	 * @brief 将页面添加到页面栈
289	 * 
290	 * @param page 页面对象
291	 * @return int 成功返回0，失败返回负值
292	 */
293	int vw_watch_push_page(lv_obj_t *page)
294	{
295	    if (page == NULL) {
296	        return -1;
297	    }
298	
299	    if (page_stack_size >= MAX_PAGE_STACK_SIZE) {
300	        return -2;
301	    }
302	    LAUNCHER_LOG("push page to stack: %p", page);
303	
304	    page_stack[page_stack_size++] = page;
305	    return 0;
306	}
307	
308	/**
309	 * @brief 从页面栈中移除页面
310	 * 
311	 * @param page 页面对象
312	 * @return int 成功返回0，失败返回负值
313	 */
314	int vw_watch_pop_page(lv_obj_t *page)
315	{
316	    if (page == NULL || page_stack_size == 0) {
317	        return -1;
318	    }
319	
320	    int i;
321	    for (i = 0; i < page_stack_size; i++) {
322	        if (page_stack[i] == page) {
323	        break;
324	        }
325	    }
326	
327	    if (i >= page_stack_size) {
328	        return -2;
329	    }
330	    LAUNCHER_LOG("pop page from stack: %p", page);
331	
332	    for (; i < page_stack_size - 1; i++) {
333	        page_stack[i] = page_stack[i + 1];
334	    }
335	
336	    page_stack_size--;
337	    return 0;
338	}
