357	    }
358	
359	    /* 再删除页面栈中的所有页面 */
360	    LAUNCHER_LOG("[BACK_HOME] Deleting %d pages from stack", page_stack_size);
361	    
362	    /* 反向删除页面栈（从栈顶开始） */
363	    for (int i = page_stack_size - 1; i >= 0; i--) {
