367	            page_stack[i] = NULL;
368	        }
369	    }
370	    page_stack_size = 0;
371	    LAUNCHER_LOG("[BACK_HOME] All pages deleted");
372	
373	    LAUNCHER_LOG("[BACK_HOME] Done");
374	    return 0;
375	}
