1837	void volc_voice_stop(void)
1838	{
1839	    bool was_running = s_running;
1840	
1841	    /* 未启动，或异常死亡后资源已由 volc_voice_start 清理 */
1842	    if (!was_running && !s_tls)
1843	        return;
1844	
1845	    s_running = false;
1846	    s_session_active = false;
1847	
1848	    if (s_recv_tid) { pthread_join(s_recv_tid, NULL); s_recv_tid = 0; }
1849	    if (s_send_tid) { pthread_join(s_send_tid, NULL); s_send_tid = 0; }
1850	
1851	    /* 仅会话还活着时礼貌收尾：异常死亡后 socket 已被服务端关闭，
1852	     * 发 FinishSession/FinishConnection 只会打一堆 ssl_write 错误 */
1853	    if (was_running && s_tls && s_tls->net.fd >= 0) {
1854	        send_finish_session(s_tls, s_session_id);
1855	        usleep(100000);
1856	        send_finish_connection(s_tls);
1857	        usleep(100000);
1858	    }
1859	
1860	    playback_stop();
1861	    if (s_nxplayer) { nxplayer_release(s_nxplayer); s_nxplayer = NULL; }
1862	    capture_deinit();
1863	    if (s_tls) {
1864	        tls_free(s_tls);
1865	        free(s_tls);
1866	        s_tls = NULL;
1867	    }
1868	
1869	    notify_ui(VOLC_CB_DISCONNECTED, NULL);
1870	    notify_state(VOLC_UI_IDLE);
1871	
1872	    syslog(LOG_INFO, "[%s] Voice session stopped\n", TAG);
1873	}
1874	
1875	bool volc_voice_is_active(void)
1876	{
1877	    return s_running && s_session_active;
1878	}
