1880	void volc_voice_interrupt(void)
1881	{
1882	    if (s_playing) {
1883	        playback_stop();
1884	        playback_init();
1885	        s_playing = false;
1886	        s_cooldown_active = false;
1887	        if (s_nxplayer) {
1888	            nxplayer_stop(s_nxplayer);
1889	            usleep(100000);
1890	            nxplayer_release(s_nxplayer);
1891	            s_nxplayer = NULL;
1892	        }
1893	        capture_deinit();
1894	        usleep(200000);
1895	        if (capture_init() == 0) capture_start();
1896	        notify_state(VOLC_UI_CONNECTED);
1897	        syslog(LOG_INFO, "[%s] playback interrupted\n", TAG);
1898	    }
1899	}
