596	
597	static void *voice_start_thread(void *arg)
598	{
599	    (void)arg;
600	    TONG_LOG("[TONG] voice_start_thread begin\n");
601	    g_start_ret = volc_voice_start(volc_event_callback);
602	    TONG_LOG("[TONG] voice_start_thread ret=%d\n", g_start_ret);
603	
604	    if (g_cancel_requested) {
605	        if (g_start_ret == 0) {
606	            /* 启动成功但用户已取消 */
607	            volc_voice_stop();
608	        }
609	        /* 启动失败的清理由volc模块内部完成 */
610	    }
611	    /* 成功时：回调会通过pending标志驱动UI到CONNECTED状态 */
612	
613	    g_starting = false;
614	    return NULL;
615	}
