617	/* 创建启动线程(按钮/自动重连共用)。调用前 UI 应已切到 CONNECTING。 */
618	static bool start_voice_session(void)
619	{
620	    g_cancel_requested = false;
621	    g_starting = true;
622	    g_start_ret = -1;
623	
624	    volc_voice_init();
625	
626	    pthread_attr_t attr;
627	    pthread_attr_init(&attr);
628	    pthread_attr_setstacksize(&attr, START_THREAD_STACK);
629	    int ret = pthread_create(&g_start_tid, &attr, voice_start_thread, NULL);
630	    pthread_attr_destroy(&attr);
631	
632	    if (ret != 0) {
633	        TONG_LOG("[TONG] start thread create failed: %d\n", ret);
634	        g_starting = false;
635	        tong_update_ui_state(TONG_STATE_ERROR, "无法启动语音服务");
636	        return false;
637	    }
638	    return true;
639	}
