323	/* Stream each mono TTS chunk straight into the WAV file on tmpfs.
324	 * The file stays mono — the es8311 playback path accepts 1-channel
325	 * WAVs (TXCHANNELS(1) mono TDM) — so no stereo doubling: a long reply
326	 * costs half the tmpfs heap, which is the hard limit on reply length
327	 * (the old stereo expansion died with ENOMEM at ~2MB / ~21s).
328	 * A negative is_last is a rollback signal from a truncated hybrid
329	 * drain: rewind the file so the classic-TTS fallback rewrites it
330	 * from the start (playback trusts ctx->written + the patched WAV
331	 * header, not the file tail). */
332	static void tts_file_cb(const unsigned char* pcm, size_t pcm_len,
333	    int is_last, void* ud)
334	{
335	    tts_file_ctx_t* ctx = ud;
336	    if (is_last < 0) {
337	        if (lseek(ctx->fd, TTS_WAV_HDR_SIZE, SEEK_SET) >= 0) {
338	            ctx->written = 0;
339	            ctx->err = 0;
340	        }
341	        return;
342	    }
343	    if (ctx->err) return;
344	    if (pcm && pcm_len > 0) {
345	        if (!s_tts_first_chunk) {
346	            struct timespec now;
347	            clock_gettime(CLOCK_MONOTONIC, &now);
348	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
349	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
350	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
351	            s_tts_first_chunk = 1;
352	        }
353	        ssize_t w = write(ctx->fd, pcm, pcm_len);
354	        if (w != (ssize_t)pcm_len) {
355	            syslog(LOG_ERR,
356	                "[%s] TTS wav write failed at %zu bytes (errno=%d)\n",
357	                TAG, ctx->written, errno);
358	            ctx->err = -ENOSPC;
359	            return;
360	        }
361	        ctx->written += pcm_len;
362	    }
363	    (void)is_last;
364	}
