314	
315	#define TTS_WAV_HDR_SIZE 44  /* keep in sync with speak()'s WAV_HDR_SIZE */
316	
317	/* Mono TTS chunks are duplicated to L=R stereo before writing.  The
318	 * es8311/I2S hardware requires a 2-channel frame (see tong_ai_ws.h
319	 * "I2S硬件要求立体声输出"); a mono stream would be mis-clocked and play
320	 * back distorted/fast.  Process the mono input in fixed sub-chunks so we
321	 * only need this one static stereo buffer regardless of the source chunk
322	 * size. */
323	#define TTS_STEREO_BUF_SAMPLES 4096   /* holds 2048 mono samples x 2ch */
324	static int16_t s_tts_stereo_buf[TTS_STEREO_BUF_SAMPLES];
325	
326	typedef struct {
327	    int fd;          /* WAV file, positioned after the 44-byte header */
328	    size_t written;  /* stereo bytes successfully written */
329	    int err;
330	} tts_file_ctx_t;
331	
332	/* Stream each mono TTS chunk into the WAV file on tmpfs as stereo
333	 * (L=R duplicated), so the es8311 playback path can run TXCHANNELS(2).
334	 * A negative is_last is a rollback signal from a truncated hybrid drain:
335	 * rewind the file so the classic-TTS fallback rewrites it from the start
336	 * (playback trusts ctx->written + the patched WAV header, not the file
337	 * tail). */
338	static void tts_file_cb(const unsigned char* pcm, size_t pcm_len,
339	    int is_last, void* ud)
340	{
341	    tts_file_ctx_t* ctx = ud;
342	    if (is_last < 0) {
343	        if (lseek(ctx->fd, TTS_WAV_HDR_SIZE, SEEK_SET) >= 0) {
344	            ctx->written = 0;
345	            ctx->err = 0;
346	        }
347	        return;
348	    }
349	    if (ctx->err) return;
350	    if (pcm && pcm_len > 0) {
351	        if (!s_tts_first_chunk) {
352	            struct timespec now;
353	            clock_gettime(CLOCK_MONOTONIC, &now);
354	            long ms = (now.tv_sec - s_tts_start.tv_sec) * 1000
355	                + (now.tv_nsec - s_tts_start.tv_nsec) / 1000000;
356	            syslog(LOG_INFO, "[%s] TTS first chunk: %ldms\n", TAG, ms);
357	            s_tts_first_chunk = 1;
358	        }
359	
360	        /* Duplicate mono -> stereo (L=R).  pcm_len is 16-bit mono bytes. */
361	        const int16_t* src = (const int16_t*)pcm;
362	        size_t frames = pcm_len / 2;
363	        size_t off = 0;
364	        while (off < frames) {
365	            size_t n = frames - off;
366	            if (n > (size_t)(TTS_STEREO_BUF_SAMPLES / 2)) {
367	                n = TTS_STEREO_BUF_SAMPLES / 2;
368	            }
369	            for (size_t i = 0; i < n; i++) {
370	                s_tts_stereo_buf[i * 2]     = src[off + i];
371	                s_tts_stereo_buf[i * 2 + 1] = src[off + i];
372	            }
373	            size_t wbytes = (n * 2) * sizeof(int16_t);
374	            ssize_t w = write(ctx->fd, s_tts_stereo_buf, wbytes);
375	            if (w != (ssize_t)wbytes) {
376	                syslog(LOG_ERR,
377	                    "[%s] TTS wav write failed at %zu bytes (errno=%d)\n",
378	                    TAG, ctx->written, errno);
379	                ctx->err = -ENOSPC;
380	                return;
381	            }
382	            ctx->written += wbytes;
383	            off += n;
384	        }
385	    }
386	    (void)is_last;
387	}
