724	
725	static void slide_gesture_handler(lv_event_t *e)
726	{
727	    lv_event_code_t code = lv_event_get_code(e);
728	    static lv_point_t start_point = {0};
729	
730	    switch (code) {
731	    case LV_EVENT_PRESSED:
732	        lv_indev_get_point(lv_indev_active(), &start_point);
733	        break;
734	
735	    case LV_EVENT_RELEASED: {
736	        lv_point_t end_point;
737	        lv_indev_get_point(lv_indev_active(), &end_point);
738	
739	        int32_t delta_x = end_point.x - start_point.x;
740	        int32_t delta_y = end_point.y - start_point.y;
741	
742	        /* 右滑退出 */
743	        if (delta_x > 50 && abs(delta_x) > abs(delta_y)) {
744	            TONG_LOG("tong_ai: right swipe, exit\n");
745	            back_btn_click_handler(NULL);
746	        }
747	        break;
748	    }
749	
750	    default:
751	        break;
752	    }
753	}
