118	static void setup_settings_button(lv_obj_t *btn) 
119	{
120	    /* 获取按钮中的图标和文本 */
121	    lv_obj_t * btn_img = lv_obj_get_child(btn, 0);  // 获取图标
122	    lv_obj_t * btn_label = lv_obj_get_child(btn, 1); // 获取文本标签
123	    
124	    /* 设置按钮样式 */
125	    static bool style_initialized = false;
126	    if (!style_initialized) {
127	        lv_style_init(&btn_style);
128	        lv_style_set_bg_opa(&btn_style, LV_OPA_10); 
129	        lv_style_set_bg_color(&btn_style, lv_color_hex(0xFFFFFF));
130	        lv_style_set_text_color(&btn_style, lv_color_white());
131	        lv_style_set_text_font(&btn_style, vw_resource_get_font(WATCH_REGULAR_FONT "_32"));
132	        lv_style_set_text_letter_space(&btn_style, 2); // 设置字符间距为2像素
133	        lv_style_set_border_width(&btn_style, 0);
134	        lv_style_set_radius(&btn_style, 32);
135	        lv_style_set_pad_all(&btn_style, 0);
136	        lv_style_set_outline_width(&btn_style, 0);
137	        /* 禁用变换效果，防止按钮按下时偏移 */
138	        lv_style_set_transform_width(&btn_style, 0);
139	        lv_style_set_transform_height(&btn_style, 0);
140	        lv_style_set_translate_x(&btn_style, 0);
141	        lv_style_set_translate_y(&btn_style, 0);
142	        style_initialized = true;
143	    }
144	
145	    /* 为按下状态单独设置样式，确保没有变换效果 */
146	    static lv_style_t btn_pressed_style;
147	    static bool pressed_style_initialized = false;
148	    if (!pressed_style_initialized) {
149	        lv_style_init(&btn_pressed_style);
150	        lv_style_set_bg_opa(&btn_pressed_style, LV_OPA_10);
151	        lv_style_set_bg_color(&btn_pressed_style, lv_color_hex(0xFFFFFF));
152	        lv_style_set_text_color(&btn_pressed_style, lv_color_white());
153	        lv_style_set_transform_width(&btn_pressed_style, 0);
154	        lv_style_set_transform_height(&btn_pressed_style, 0);
155	        lv_style_set_translate_x(&btn_pressed_style, 0);
156	        lv_style_set_translate_y(&btn_pressed_style, 0);
157	        pressed_style_initialized = true;
158	    }
159	    
160	    lv_obj_add_style(btn, &btn_style, 0);
161	    lv_obj_add_style(btn, &btn_pressed_style, LV_STATE_PRESSED);
162	    
163	    lv_obj_set_size(btn, WATCH_BTN_WIDTH, WATCH_BTN_HEIGHT);
164	    lv_obj_clear_flag(btn, LV_OBJ_FLAG_SCROLLABLE);  // 清除滚动标志
165	    
166	    /* 重置按钮的布局方式，确保我们的对齐设置生效 */
167	    lv_obj_set_flex_flow(btn, LV_FLEX_FLOW_ROW);
168	    lv_obj_set_flex_align(btn, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
169	    
170	    /* 设置图标样式 - 64x64图标，距离按钮左侧18px，上下居中 */
171	    if (btn_img) {
172	        lv_obj_set_size(btn_img, 64, 64);  // 图标大小64x64
173	        lv_obj_set_style_pad_left(btn, 18, 0);  // 按钮左侧内边距18px
174	        lv_obj_align(btn_img, LV_ALIGN_CENTER, 0, 0);
175	    }
176	
177	    /* 设置文本样式 - 距离图标右侧24px，上下居中 */
178	    if (btn_label) {
179	        lv_obj_set_style_text_color(btn_label, lv_color_white(), 0);
180	        lv_obj_set_style_text_font(btn_label, vw_resource_get_font(WATCH_REGULAR_FONT "_32"), 0);
181	        lv_obj_set_style_pad_left(btn_label, 24, 0);  // 文本距离图标24px
182	        lv_obj_align(btn_label, LV_ALIGN_CENTER, 0, 0);
183	    }
184	    
185	    lv_obj_add_flag(btn, LV_OBJ_FLAG_EVENT_BUBBLE);
186	}
