216	static void slide_gesture_handler(lv_event_t *e) 
217	{
218	    lv_event_code_t code = lv_event_get_code(e);
219	
220	    static lv_point_t start_point = {0};
221	    static bool is_dragging = false;
222	
223	    switch(code) {
224	        case LV_EVENT_PRESSED:
225	            forbift_btn_click();
226	            lv_indev_get_point(lv_indev_active(), &start_point);
227	            is_dragging = true;
228	            break;
229	        
230	        case LV_EVENT_RELEASED:
231	            if(is_dragging) {
232	                lv_point_t end_point;
233	                lv_indev_get_point(lv_indev_active(), &end_point);
234	                
235	                int32_t delta_x = end_point.x - start_point.x;
236	                int32_t delta_y = end_point.y - start_point.y;
237	
238	                if(delta_x > 50) 
239	                {
240	                    if(abs(delta_x) > abs(delta_y))
241	                    {
242	                        if(settings_base != NULL)  // 左滑：退出当前页面（详情页或列表页）
243	                        {
244	                            // 将页面从页面栈弹出
245	                            vw_watch_pop_page(settings_base);
246	                            lv_obj_del(settings_base); //删除窗口
247	                            settings_base = NULL;
248	                        }
249	                    }
250	                } 
251	                else
252	                {
253	                    unforbift_btn_click();
254	                }
255	            }
256	            is_dragging = false;
257	            break;
258	            
259	        default:
260	            break;
261	    }
262	}
