431	/* ========== volc事件回调 (从recv_thread/start_thread调用) ========== */
432	
433	static void volc_event_callback(volc_callback_type_t type, const char *data)
434	{
435	    switch (type) {
436	    case VOLC_CB_UI_STATE:
437	        if (data) {
438	            g_pending_volc_state = (volc_ui_state_t)(unsigned char)data[0];
439	            g_pending_flags |= PENDING_STATE;
440	        }
441	        break;
442	    case VOLC_CB_ERROR_MSG:
443	        if (data && g_pending_error_msg) {
444	            strncpy(g_pending_error_msg, data, PENDING_ERROR_MSG_SIZE - 1);
445	            g_pending_error_msg[PENDING_ERROR_MSG_SIZE - 1] = '\0';
446	            g_pending_flags |= PENDING_ERROR;
447	        }
448	        break;
449	    case VOLC_CB_CONNECTED:
450	        /* 由 VOLC_CB_UI_STATE(VOLC_UI_CONNECTED) 处理 */
451	        break;
452	    case VOLC_CB_USER_TEXT:
453	        if (data) {
454	            syslog(LOG_INFO, "[TONG] ASR: \"%s\"\n", data);
455	
456	            /* 智能家居指令检测（优先于UI模式切换） */
457	            int hc_ret = home_control_voice_execute(data);
458	            if (hc_ret == HOME_CTRL_NET_FAIL) {
459	                /* 匹配到设备但网络失败 */
460	                syslog(LOG_INFO,
461	                    "[TONG] home ctrl net fail: \"%s\"\n", data);
462	                volc_play_local_wav(HOME_CTRL_FAIL_WAV);
463	                break;
464	            } else if (hc_ret == HOME_CTRL_NO_MATCH) {
465	                /* 有开关动作词但未匹配到设备 */
466	                syslog(LOG_INFO,
467	                    "[TONG] home ctrl no match: \"%s\"\n", data);
468	                volc_play_local_wav(HOME_CTRL_NOT_FOUND_WAV);
469	                break;
470	            }
471	            /* HOME_CTRL_OK: 指令成功，继续正常流程
472	             * HOME_CTRL_NONE: 无关指令，继续UI模式切换检测 */
473	
474	            int matched = 0;
475	            ui_mode_t switch_target = UI_MODE_EXPRESSION;
476	            /* 策略1: 完整短语匹配（含发音变体） */
477	            if (strstr_any(data, VAR_CHAOWAN) ||
478	                strstr_any(data, VAR_BIAOQING)) {
479	                matched = 1;
480	                switch_target = UI_MODE_EXPRESSION;
481	            } else if (strstr_any(data, VAR_BIOPAN)) {
482	                /* "表盘"等变体 → 切换到手表模式 */
483	                matched = 1;
484	                switch_target = UI_MODE_WATCH;
485	            }
486	            /* 策略2: 动作词+目标词变体组合匹配 */
487	            if (!matched) {
488	                int has_action = (strstr(data, "切换") ||
489	                    strstr(data, "打开") ||
490	                    strstr(data, "进入") ||
491	                    strstr(data, "回到") ||
492	                    strstr(data, "返回"));
493	                if (has_action) {
494	                    if (strstr_any(data, VAR_CHAOWAN) ||
495	                        strstr_any(data, VAR_BIAOQING)) {
496	                        matched = 1;
497	                        switch_target = UI_MODE_EXPRESSION;
498	                    } else if (strstr_any(data, VAR_BIOPAN)) {
499	                        matched = 1;
500	                        switch_target = UI_MODE_WATCH;
501	                    }
502	                }
503	            }
504	            if (matched) {
505	                syslog(LOG_INFO, "[TONG] UI mode switch triggered: %s (target=%d)\n",
506	                       data, (int)switch_target);
507	                int ret = ui_mode_switch_runtime(switch_target, lv_scr_act());
508	                if (ret != 0)
509	                    syslog(LOG_INFO, "[TONG] Failed to switch UI mode: %d\n", ret);
510	                else
511	                    syslog(LOG_INFO, "[TONG] UI mode switched (runtime, target=%d)\n",
512	                           (int)switch_target);
513	                return;  /* 切换后不再处理本条文本 */
514	            }
515	
516	            /* 音量本地调节——静默执行硬件操作，不抑制TTS */
517	            try_volume_adjust(data);
518	        }
519	        break;
520	    case VOLC_CB_DISCONNECTED:
521	        g_pending_flags |= PENDING_DISCONNECTED;
522	        break;
523	    }
524	}

